import React from 'react';

function Home() {
  // Inline styles object
  const styles = {
    global: `
      * {
        margin: 0;
        padding: 0;
        box-sizing: border-box;
      }

      body {
        font-family: Arial, sans-serif;
        background: linear-gradient(to bottom, #1f0033, #6a5acd);
        color: #000;
      }
    `,
    header: {
      background: 'linear-gradient(to right, #4b0082, #8a2be2)',
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      padding: '20px 40px',
      color: 'white'
    },
    headerContainer: {
      position: 'relative',
      height: '150px',
      overflow: 'hidden'
    },
    headerTitle: {
      position: 'absolute',
      top: '30px',
      left: '30px',
      fontSize: '2.5rem',
      fontWeight: 'bold',
      color: 'white',
      zIndex: 2,
      textShadow: '2px 2px 5px rgba(0,0,0,0.6)'
    },
    headerBg: {
      width: '500px',
      height: '500px',
      display: 'block'
    },
    nav: {
      listStyle: 'none',
      display: 'flex',
      gap: '25px'
    },
    navLink: {
      color: 'white',
      textDecoration: 'none',
      fontWeight: 'bold',
      fontSize: '1em'
    },
    main: {
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      backgroundColor: '#a6a0be',
      padding: '60px 40px'
    },
    welcomeText: {
      width: '55%'
    },
    welcomeTitle: {
      fontSize: '2em',
      marginBottom: '20px'
    },
    welcomeParagraph: {
      fontSize: '1.05em',
      color: '#2c2c2c',
      lineHeight: '1.6'
    },
    cubeImage: {
      width: '40%'
    },
    cubeImg: {
      maxWidth: '100%',
      borderRadius: '10px'
    },
    getStartedContainer: {
      width: '100%',
      padding: '20px 40px',
      display: 'flex',
      justifyContent: 'flex-start',
      marginBottom: '30px'
    },
    getStartedButton: {
      display: 'inline-block',
      padding: '12px 24px',
      backgroundColor: '#5c27fe',
      color: 'white',
      textDecoration: 'none',
      fontWeight: 'bold',
      borderRadius: '8px',
      transition: 'background-color 0.3s ease',
      position: 'relative'
    },
    footer: {
      backgroundColor: '#1c1c1c',
      color: '#f2f2f2',
      padding: '30px 20px',
      fontFamily: "'Segoe UI', sans-serif",
      fontSize: '14px'
    },
    footerContent: {
      display: 'flex',
      flexWrap: 'wrap',
      justifyContent: 'space-between',
      maxWidth: '1200px',
      margin: 'auto'
    },
    footerSection: {
      flex: 1,
      minWidth: '200px',
      margin: '10px'
    },
    footerTitle: {
      color: '#ffffff',
      marginBottom: '10px'
    },
    footerLink: {
      color: '#80dfff',
      textDecoration: 'none'
    },
    socialStickers: {
      display: 'flex',
      gap: '15px',
      padding: '10px',
      justifyContent: 'center'
    },
    socialImg: {
      width: '40px',
      height: '40px',
      transition: 'transform 0.3s ease'
    }
  };

  // Add global styles
  React.useEffect(() => {
    const styleElement = document.createElement('style');
    styleElement.textContent = styles.global;
    document.head.appendChild(styleElement);

    // Add hover effects
    const hoverStyles = `
      .social-img:hover {
        transform: scale(1.1);
      }
      .nav-link:hover {
        opacity: 0.8;
      }
      .footer-link:hover {
        text-decoration: underline;
      }
      .get-started-button:hover {
        background-color: #4a1fd4;
      }
      @media (max-width: 768px) {
        .footer-content {
          flex-direction: column !important;
          text-align: center;
        }
      }
    `;
    
    const hoverStyleElement = document.createElement('style');
    hoverStyleElement.textContent = hoverStyles;
    document.head.appendChild(hoverStyleElement);

    return () => {
      document.head.removeChild(styleElement);
      document.head.removeChild(hoverStyleElement);
    };
  }, []);

  // Mock Link component since we don't have React Router
  const Link = ({ to, children, className, style }) => (
    <a 
      href={to} 
      className={className} 
      style={style}
      onClick={(e) => e.preventDefault()}
    >
      {children}
    </a>
  );

  return (
    <>
      <header style={styles.header}>
        <div style={styles.headerContainer} className="header-container">
          <img 
            src="/images/header background.jpg" 
            alt="Header Background" 
            style={styles.headerBg}
          />
          <h1 style={styles.headerTitle}>
            <span style={{ fontWeight: 'bold' }}>SonicG</span>Low<br />
            <span style={{ fontWeight: 'bold' }}>Cube</span>
          </h1>
        </div>
        <nav>
          <ul style={styles.nav}>
            <li>
              <Link to="/" style={styles.navLink} className="nav-link">Home</Link>
            </li>
            <li>
              <Link to="/resources" style={styles.navLink} className="nav-link">Resources</Link>
            </li>
            <li>
              <Link to="/cube" style={styles.navLink} className="nav-link">SonicGlow Cube</Link>
            </li>
            <li>
              <Link 
                to="/about" 
                style={{...styles.navLink, opacity: 0.8}} 
                className="nav-link active"
              >
                About Us
              </Link>
            </li>
          </ul>
        </nav>
      </header>

      <main style={styles.main}>
        <section style={styles.welcomeText} className="welcome-text">
          <h2 style={styles.welcomeTitle}>Welcome to SonicGlow Cube</h2>
          <p style={styles.welcomeParagraph}>
            <strong>SonicGlow Cube</strong> is an innovative 3D LED display system designed to light up your world with dynamic patterns, animations, and custom text.
            <br /><br />
            Explore pre-designed effects or create your own using our web interface!
          </p>
          <div style={styles.getStartedContainer} className="get-started-container">
            <Link 
              to="/Section1" 
              style={styles.getStartedButton}
              className="get-started-button"
            >
              Get Started
            </Link>
          </div>
        </section>

        <section style={styles.cubeImage} className="cube-image">
          <img 
            src="/images/soniccube1.png" 
            alt="SonicGlow LED Cube" 
            style={styles.cubeImg}
          />
        </section>
      </main>

      <footer style={styles.footer}>
        <div style={styles.footerContent} className="footer-content">
          <div style={styles.footerSection} className="footer-left">
            <h3 style={styles.footerTitle}>SonicGlow Cube</h3>
            <p>Created by Hardware Hackers<br />University of Moratuwa – First-Year Hardware Project</p>
          </div>
          <div style={styles.socialStickers} className="social-stickers">
            <a href="https://www.facebook.com/" target="_blank" rel="noopener noreferrer">
              <img 
                src="/images/fb.png" 
                alt="Facebook" 
